package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.service.MerchantActor;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import static org.junit.jupiter.api.Assertions.*;

class JdbcAssessmentViewsTest extends JdbcAssessmentSnapshotsTest {
 AssessmentViews views;
 @BeforeEach void views(){views=new AssessmentViews(db,snapshots,new OperatorIdentity(jdbc,null,new DataSourceTransactionManager(jdbc.getDataSource())));}
 MerchantActor staff(){jdbc.update("INSERT INTO staff_account(id,merchant_id,role,account,status) VALUES(8,1,'STAFF','monthly-view-staff','ACTIVE')");return new MerchantActor(8,1,"STAFF",session(8,"staff_account","STAFF","merchant-account",1L),Instant.now().plusSeconds(600));}
 @Test void contextIsReadOnlyAndVersionDoesNotDependOnHistoryPage(){prepare();clock.value=end;for(int i=0;i<21;i++)snapshots.create(operator,key(),request(i));var c=views.context(operator,1,period);assertEquals(21L,c.get("revision"));assertEquals(21,db.mapper.valueToTree(c.get("latest")).path("revision").asInt());assertEquals(1,((List<?>)views.history(operator,1,period,2).get("items")).size());assertEquals(21,count("assessment_snapshot"));assertEquals(0,count("assessment_snapshot_fact"));assertEquals(false,views.context(merchant,period).get("can_settle"));assertEquals(true,c.get("can_settle"));assertEquals("READY",c.get("state"));assertEquals(0L,views.context(other,period).get("revision"));}
 @Test void currentOpenMonthHasNoSettlementAndReadingDoesNotWrite(){prepare();var c=views.context(operator,1,period);assertEquals("MONTH_OPEN",c.get("state"));assertEquals(false,c.get("can_settle"));assertEquals(0L,c.get("revision"));assertEquals(0,count("assessment_month"));assertEquals(0,count("assessment_snapshot"));clock.value=end;policies.status(operator,policyId,key(),statusBody(2,"STOPPED"));assertFalse(db.mapper.valueToTree(views.context(operator,1,period)).path("policy").isNull());}
 @Test void managersCannotReadOtherStoreSnapshotsAndStaffCannotReadStoreScores(){prepare();long id=settle(0).path("id").asLong();assertEquals(id,((Number)views.detail(merchant,id).get("id")).longValue());assertEquals(404,code(()->views.detail(other,id)));assertEquals(404,code(()->views.facts(other,id,1)));var employee=staff();assertEquals(403,code(()->views.context(employee,period)));assertEquals(403,code(()->views.history(employee,period,1)));assertEquals(403,code(()->views.detail(employee,id)));assertEquals(403,code(()->views.facts(employee,id,1)));}
 @Test void staffAttributionIsOnlyOwnLatestFrozenCountAndNoNewCustomerData(){prepare();invitation("VERIFIED_WECHAT");var r=settle(0);var me=views.staff(merchant,period);assertEquals(1L,((Map<?,?>)me.get("attribution")).get("included"));assertEquals(1L,me.get("revision"));var employee=staff();assertEquals(0L,((Map<?,?>)views.staff(employee,period).get("attribution")).get("included"));assertEquals(Set.of("role","staff_id","merchant_id","period_month","timezone","state","revision","captured_from","captured_to","attribution"),me.keySet());assertFalse(db.json(me).contains("record_id"));assertFalse(db.json(me).contains("qualified_at"));snapshots.create(operator,key(),request(1));assertEquals(2L,views.staff(merchant,period).get("revision"));assertEquals("NO_SNAPSHOT",views.staff(other,period).get("state"));assertEquals(r.path("merchant_id").asLong(),me.get("merchant_id"));}
 @Test void everyReadRechecksCurrentIdentityAndIndependentPermission(){prepare();long id=settle(0).path("id").asLong();jdbc.update("UPDATE operator_account SET can_assessment=0,can_points=1 WHERE id=1");assertEquals(403,code(()->views.context(operator,1,period)));assertEquals(403,code(()->views.history(operator,1,period,1)));jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",merchant.session());assertEquals(401,code(()->views.staff(merchant,period)));assertEquals(401,code(()->views.detail(merchant,id)));assertEquals(401,code(()->views.facts(merchant,id,1)));}
 @Test void filteredHistoryAndFactsRetainOldRevisionsAndRejectInvalidPagination(){prepare();formalOrder(10,start.plusSeconds(1000),true);var first=settle(0);jdbc.update("UPDATE pickup_check SET is_deleted=1 WHERE order_id=10");var second=settle(1);assertEquals(2L,views.history(merchant,period,1).get("total"));assertEquals(0L,views.history(other,period,1).get("total"));assertEquals(1L,views.facts(merchant,first.path("id").asLong(),1).get("total"));assertEquals("20.00",db.mapper.valueToTree(views.detail(merchant,first.path("id").asLong())).path("summary").path("total_score").asText());assertTrue(db.mapper.valueToTree(views.detail(merchant,second.path("id").asLong())).path("summary").path("total_score").isNull());assertEquals(400,code(()->views.history(operator,1,period,0)));}
}
